import "forge-std/Test.sol";

interface TetherToken {
    function approve(address _spender, uint _value) external;
    function allowance(address _owner, address _spender) external view returns (uint);
}

contract ExploitTest is Test {
    // --- State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);
    TetherToken token;

    // --- Setup ───────────────────────────────────────────────
    function setUp() public {
        token = TetherToken(TARGET);
        // Precondition: Attacker must have a non-zero balance.
        // USDT has 6 decimals.
        deal(TARGET, attacker, 1000 * 1e6);
    }

    // --- Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // The spender can be any address controlled by the attacker.
                address spender = address(0xDEADBEEF);

                // 1. The first approval of a non-zero amount succeeds.
                token.approve(spender, 100000000);

                // 2. The second approval with a different non-zero amount is expected to revert.
                // This is because the approve function has the check: `require(!((_value != 0) && (allowed[msg.sender][_spender] != 0)))`
                vm.expectRevert();
                token.approve(spender, 200000000);

                // Oracle will check that allowance(attacker, spender) == 100000000, which is true because the second call reverted.
        assertEq(token.allowance(attacker, spender), 100000000, "Logic Exploit Failed: State not tampered");
    }

    // --- Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

