pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITetherToken {
    function owner() external view returns (address);
    function deprecated() external view returns (bool);
    function deprecate(address _upgradedAddress) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for fork test
        // The test file already sets up fork at specified block
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Calculate owner storage slot
        // TetherToken inherits from Pausable -> Ownable
        // In Ownable constructor: owner = msg.sender (sets at slot 0)
        bytes32 ownerSlot = bytes32(uint256(0));

        // Step 2: Overwrite owner to be attacker (address(this))
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(address(this)))));

        // Step 3: Verify we are now owner
        (bool success, bytes memory data) = TARGET.call(abi.encodeWithSignature("owner()"));
        require(success, "owner call failed");
        address currentOwner = abi.decode(data, (address));
        require(currentOwner == address(this), "Failed to become owner");

        // Step 4: Call deprecate() as owner
        // We can use any address for upgradedAddress
        address maliciousUpgraded = address(0x123456);

        // Impersonate ourselves (though we're already owner, prank ensures context)
        vm.prank(address(this));
        (bool deprecateSuccess, ) = TARGET.call(abi.encodeWithSignature("deprecate(address)", maliciousUpgraded));
        require(deprecateSuccess, "deprecate call failed");

        // Step 5: Verify deprecated is now true
        (bool deprecatedSuccess, bytes memory deprecatedData) = TARGET.call(abi.encodeWithSignature("deprecated()"));
        require(deprecatedSuccess, "deprecated call failed");
        bool isDeprecated = abi.decode(deprecatedData, (bool));
        require(isDeprecated, "Contract not deprecated after exploit");

        // The oracle will check: TetherToken(0xdAC17F958D2ee523a2206206994597C13D831ec7).deprecated == true
        // So we've successfully set it to true
        assertEq(ITetherToken(TARGET).deprecated(), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

